package com.greenocean.backend.listener.planning;

import com.greenocean.backend.listener.live.*;
import com.greenocean.backend.common.exception.ConflictException;
import jakarta.validation.constraints.*;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.*;import java.util.*;
import static com.greenocean.backend.listener.planning.ListenerSupportPolicy.*;

@Service @Transactional(noRollbackFor=LiveSupportException.class)
public class ListenerBookings {
 private final ListenerSupportPolicy p;private final ListenerCalendar calendar;private final LiveSupportService live;
 public ListenerBookings(ListenerSupportPolicy p,ListenerCalendar calendar,LiveSupportService live){this.p=p;this.calendar=calendar;this.live=live;}
 public record Reservation(@NotNull UUID listenerId,@NotNull Instant startsAt,@NotNull UUID clientKey,boolean reminders){}
 public void reconcile(){live.reconcile();var rows=p.db.queryForList("SELECT id,member_id,listener_id,status,reminders FROM listener_bookings WHERE status IN('MEMBER_NO_SHOW','LISTENER_NO_SHOW','CANCELLED_BY_SERVICE','EXPIRED') ORDER BY starts_at DESC LIMIT 100");for(var b:rows){p.notice((UUID)b.get("member_id"),(UUID)b.get("id"),(String)b.get("status"),(Boolean)b.get("reminders"));p.notice((UUID)b.get("listener_id"),(UUID)b.get("id"),(String)b.get("status"),(Boolean)b.get("reminders"));}}
 private Map<String,Object> owned(UUID id,UUID user,boolean lock){var rows=p.db.queryForList("SELECT * FROM listener_bookings WHERE id=? AND (member_id=? OR listener_id=?)"+(lock?" FOR UPDATE":""),id,user,user);if(rows.isEmpty())throw denied(404,"BOOKING_NOT_FOUND","Support booking was not found.");return rows.getFirst();}
 public Map<String,Object> view(UUID id,UUID user){owned(id,user,false);return p.db.queryForMap("SELECT b.id,b.listener_id,b.starts_at,b.ends_at,b.timezone,b.status,b.reason_code,b.revision,b.checked_in_at,b.live_request_id,b.reminders,b.rescheduled_from,p.display_name AS peer_name,CASE WHEN b.member_id=? THEN b.listener_id ELSE b.member_id END AS peer_id,b.listener_id=? AS listener_side,listener_support_now() AS server_time FROM listener_bookings b JOIN profiles p ON p.user_id=CASE WHEN b.member_id=? THEN b.listener_id ELSE b.member_id END WHERE b.id=?",user,user,user,id);}
 public List<Map<String,Object>> mine(UUID user,int page){reconcile();return p.db.queryForList("SELECT id FROM listener_bookings WHERE member_id=? OR listener_id=? ORDER BY starts_at DESC,id DESC LIMIT 20 OFFSET ?",UUID.class,user,user,Math.min(1000,Math.max(0,page))*20).stream().map(id->view(id,user)).toList();}
 public Map<String,Object> reserve(UUID member,Reservation in){p.require("BOOKING");p.eligible(member);p.listener(in.listenerId());p.lock(member,in.listenerId());p.bound(member,"BOOK",30);if(member.equals(in.listenerId())||p.truth("SELECT live_pair_blocked(?,?)",member,in.listenerId()))throw denied(409,"SLOT_UNAVAILABLE","This listener slot is unavailable.");
  var retry=p.db.queryForList("SELECT * FROM listener_bookings WHERE member_id=? AND client_key=?",member,in.clientKey());if(!retry.isEmpty()){var b=retry.getFirst();if(!in.listenerId().equals(b.get("listener_id"))||!in.startsAt().equals(instant(b.get("starts_at"))))throw denied(409,"IDEMPOTENCY_CONFLICT","This retry key belongs to another reservation.");return view((UUID)b.get("id"),member);}
  if(p.db.queryForObject("SELECT count(*) FROM listener_bookings WHERE member_id=? AND status IN('CONFIRMED','CHECKED_IN','HANDOFF_REQUESTED','ACTIVE') AND reserved_until>listener_support_now()",Integer.class,member)>=p.limits().upcomingLimit())throw denied(409,"BOOKING_LIMIT","Cancel or complete an upcoming booking before reserving another.");
  var slot=calendar.slots(member,in.listenerId(),10000,null).items().stream().filter(s->s.startsAt().equals(in.startsAt())).findFirst().orElseThrow(()->denied(409,"SLOT_UNAVAILABLE","The slot is no longer bookable. Refresh genuine availability."));
  UUID id=UUID.randomUUID();try{p.db.update("INSERT INTO listener_bookings(id,member_id,listener_id,client_key,rule_id,exception_id,timezone,starts_at,ends_at,reserved_until,reminders) VALUES(?,?,?,?,?,?,?,?,?,?,?)",id,member,in.listenerId(),in.clientKey(),slot.ruleId(),slot.exceptionId(),slot.timezone(),date(slot.startsAt()),date(slot.endsAt()),date(slot.endsAt().plusSeconds(p.limits().bufferSeconds()+p.limits().handoffSeconds())),in.reminders());}catch(DataIntegrityViolationException race){throw new ConflictException("The slot was reserved concurrently; refresh availability.");}
  p.notice(member,id,"BOOKING_CONFIRMED",in.reminders());p.notice(in.listenerId(),id,"BOOKING_CONFIRMED",in.reminders());return view(id,member);
 }
 public Map<String,Object> cancel(UUID id,UUID actor){p.liveLock();reconcile();var first=owned(id,actor,false);p.lock((UUID)first.get("member_id"),(UUID)first.get("listener_id"));var b=owned(id,actor,true);String state=(String)b.get("status");if(Set.of("CANCELLED_BY_MEMBER","CANCELLED_BY_LISTENER","CANCELLED_BY_SERVICE","MEMBER_NO_SHOW","LISTENER_NO_SHOW","EXPIRED").contains(state))return view(id,actor);if(!Set.of("CONFIRMED","CHECKED_IN","HANDOFF_REQUESTED").contains(state))throw denied(409,"BOOKING_NOT_CANCELLABLE","End an active session through its live conversation controls.");
  if(b.get("live_request_id")!=null)p.db.update("UPDATE live_support_requests SET status='CANCELLED',reason_code='BOOKING_CANCELLED',ended_at=clock_timestamp() WHERE id=? AND status IN('REQUESTED','ACCEPTED')",b.get("live_request_id"));String next=actor.equals(b.get("member_id"))?"CANCELLED_BY_MEMBER":"CANCELLED_BY_LISTENER";p.db.update("UPDATE listener_bookings SET status=?,reason_code='PARTICIPANT_CANCELLED',revision=revision+1 WHERE id=?",next,id);p.notice((UUID)b.get("member_id"),id,next,(Boolean)b.get("reminders"));p.notice((UUID)b.get("listener_id"),id,next,(Boolean)b.get("reminders"));return view(id,actor);
 }
 @Transactional public Map<String,Object> reschedule(UUID id,UUID member,Reservation in){var b=owned(id,member,false);if(!member.equals(b.get("member_id")))throw denied(403,"BOOKING_OWNER_REQUIRED","Only the member can select a replacement reservation.");var people=new TreeSet<UUID>(Comparator.comparing(UUID::toString));people.add(member);people.add((UUID)b.get("listener_id"));people.add(in.listenerId());for(UUID person:people)p.lock(person,person);b=owned(id,member,true);
  var retry=p.db.queryForList("SELECT id FROM listener_bookings WHERE member_id=? AND client_key=? AND rescheduled_from=?",UUID.class,member,in.clientKey(),id);if(!retry.isEmpty())return reserve(member,in);
  if(!"CONFIRMED".equals(b.get("status"))||!instant(b.get("starts_at")).isAfter(p.now()))throw denied(409,"BOOKING_CHANGED","Only a future confirmed booking can be rescheduled.");p.db.update("UPDATE listener_bookings SET status='CANCELLED_BY_MEMBER',reason_code='RESCHEDULED',revision=revision+1 WHERE id=?",id);var replacement=reserve(member,in);p.db.update("UPDATE listener_bookings SET rescheduled_from=? WHERE id=?",id,replacement.get("id"));p.notice((UUID)b.get("listener_id"),id,"BOOKING_CHANGED",(Boolean)b.get("reminders"));return view((UUID)replacement.get("id"),member);
 }
 public Map<String,Object> checkin(UUID id,UUID member){p.liveLock();reconcile();var b=owned(id,member,false);if(!member.equals(b.get("member_id")))throw denied(403,"BOOKING_OWNER_REQUIRED","Only the member can check in.");p.lock(member,(UUID)b.get("listener_id"));b=owned(id,member,true);p.require("BOOKING");p.eligible(member);p.listener((UUID)b.get("listener_id"));Instant now=p.now(),start=instant(b.get("starts_at"));if(now.isBefore(start.minusSeconds(p.limits().checkinSeconds())))throw denied(409,"CHECKIN_NOT_OPEN","Check-in opens shortly before the server-confirmed appointment time.");if(!now.isBefore(start.plusSeconds(p.limits().graceSeconds())))throw denied(409,"CHECKIN_CLOSED","The check-in grace period ended. Choose another genuine slot if available.");if(Set.of("CHECKED_IN","HANDOFF_REQUESTED","ACTIVE").contains(b.get("status")))return view(id,member);if(!"CONFIRMED".equals(b.get("status")))throw denied(409,"BOOKING_CHANGED","This booking can no longer be checked in.");p.db.update("UPDATE listener_bookings SET status='CHECKED_IN',checked_in_at=listener_support_now(),revision=revision+1 WHERE id=?",id);return view(id,member);}
 public Map<String,Object> handoff(UUID id,UUID member){p.liveLock();reconcile();var b=owned(id,member,false);if(!member.equals(b.get("member_id")))throw denied(403,"BOOKING_OWNER_REQUIRED","Only the member can request the scheduled handoff.");p.lock(member,(UUID)b.get("listener_id"));b=owned(id,member,true);p.require("BOOKING");p.eligible(member);p.listener((UUID)b.get("listener_id"));if(b.get("live_request_id")!=null)return Map.of("booking",view(id,member),"request",live.get((UUID)b.get("live_request_id"),member));if(!"CHECKED_IN".equals(b.get("status"))||p.now().isBefore(instant(b.get("starts_at"))))throw denied(409,"HANDOFF_NOT_OPEN","Check in and wait for the appointment start before requesting a genuinely ready listener.");if(!p.truth("SELECT live_listener_ready(?)",b.get("listener_id")))throw denied(409,"LISTENER_NOT_READY","The listener is not currently ready. No conversation was created.");var request=live.createScheduled(member,id,(UUID)b.get("listener_id"),id);p.db.update("UPDATE listener_bookings SET live_request_id=?,status='HANDOFF_REQUESTED',revision=revision+1 WHERE id=?",request.id(),id);return Map.of("booking",view(id,member),"request",request);}
}
